def sort_numbers(numbers: str) -> str:
    numberals = numbers.split()

    numeral_to_num = {
        'zero': 0,
        'one': 1,
        'two': 2,
        'three': 3,
        'four': 4,
        'five': 5,
        'six': 6,
        'seven': 7,
        'eight': 8,
        'nine': 9
    }

    num_list = [numeral_to_num[num] for num in numberals]
    sorted_nums = sorted(num_list)

    num_to_numeral = {v: k for k, v in numeral_to_num.items()}
    sorted_numberals = [num_to_numeral[num] for num in sorted_nums]

