def rolling_max(numbers: List[int], k: int) -> List[int]:
    if not numbers:
        return []

    rolling_max_list = []
    window = []

    for i in range(len(numbers)):
        if i >= k and window[0] == numbers[i - k]:
            window.pop(0)

        while window and window[-1] < numbers[i]:
            window.pop()

        window.append(numbers[i])

        if i >= k - 1:
