def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            if sub_arr[i] != sub_arr[-i - 1]:
                changes += 1
        return changes

    min_changes = float('inf')
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            sub_arr = arr[i:j+1]
            changes = count_changes(sub_arr)
            if changes < min_changes:
                min_changes = changes

    return min_changes

